CREATE TABLE gateway_requests (
    id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,
    tenant_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    workspace_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    node_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    gateway_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    api_key_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    actor_user_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    actor_epoch BIGINT NOT NULL CHECK(actor_epoch>=0),
    alias_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    alias_revision BIGINT NOT NULL,
    deployment_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    deployment_revision BIGINT NOT NULL CHECK(deployment_revision BETWEEN 1 AND 9007199254740991),
    maximum_output_tokens INTEGER NOT NULL CHECK(maximum_output_tokens BETWEEN 1 AND 512),
    maximum_context_tokens INTEGER NOT NULL CHECK(maximum_context_tokens BETWEEN 1 AND 65536),
    maximum_request_seconds INTEGER NOT NULL CHECK(maximum_request_seconds BETWEEN 1 AND 300),
    stream BOOLEAN NOT NULL CHECK(stream IN(0,1)),
    state VARCHAR(16) NOT NULL CHECK(state IN('admitted','reported','reconciled')),
    capacity_held BOOLEAN NOT NULL DEFAULT true CHECK(capacity_held IN(0,1)),
    admitted_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    deadline_at DATETIME(6) NOT NULL,
    resolved_at DATETIME(6),
    outcome JSON,
    outcome_sha256 VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin CHECK(outcome_sha256 IS NULL OR REGEXP_LIKE(outcome_sha256,'^[a-f0-9]{64}$','c')),
    reported_at DATETIME(6),
    reconciled_by CHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
    reconciled_at DATETIME(6),
    reconciliation_reason VARCHAR(500),
    active_recovery_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
    UNIQUE(tenant_id,workspace_id,id),
    KEY gateway_request_held_deployment_idx(deployment_id,capacity_held),
    KEY gateway_request_owner_idx(tenant_id,workspace_id,actor_user_id,admitted_at DESC,id DESC),
    KEY gateway_request_instance_idx(tenant_id,workspace_id,gateway_id,admitted_at DESC,id DESC),
    CONSTRAINT gateway_request_actor_fk FOREIGN KEY(actor_user_id) REFERENCES users(id),
    CONSTRAINT gateway_request_reconciler_fk FOREIGN KEY(reconciled_by) REFERENCES users(id),
    CONSTRAINT gateway_request_instance_scope_fk FOREIGN KEY(tenant_id,workspace_id,node_id,gateway_id) REFERENCES gateway_instances(tenant_id,workspace_id,node_id,id),
    CONSTRAINT gateway_request_key_scope_fk FOREIGN KEY(tenant_id,workspace_id,api_key_id) REFERENCES api_keys(tenant_id,workspace_id,id),
    CONSTRAINT gateway_request_alias_revision_fk FOREIGN KEY(tenant_id,workspace_id,alias_id,alias_revision) REFERENCES model_alias_history(tenant_id,workspace_id,alias_id,revision),
    CONSTRAINT gateway_request_deployment_scope_fk FOREIGN KEY(tenant_id,workspace_id,node_id,deployment_id) REFERENCES deployments(tenant_id,workspace_id,node_id,id),
    CONSTRAINT gateway_request_deadline_order CHECK(deadline_at>admitted_at),
    CONSTRAINT gateway_request_admission_holds CHECK(state<>'admitted' OR capacity_held),
    CONSTRAINT gateway_request_reconciled_releases CHECK(state<>'reconciled' OR NOT capacity_held),
    CONSTRAINT gateway_request_outcome_shape CHECK(outcome IS NULL OR (JSON_TYPE(outcome)='OBJECT' AND OCTET_LENGTH(CAST(outcome AS CHAR CHARACTER SET utf8mb4))<=4096 AND JSON_LENGTH(outcome)=6 AND JSON_CONTAINS_PATH(outcome,'all','$.request_id','$.status','$.error_code','$.usage','$.elapsed_milliseconds','$.output_started') AND JSON_UNQUOTE(JSON_EXTRACT(outcome,'$.request_id'))=id)),
    CONSTRAINT gateway_request_outcome_release CHECK(outcome IS NULL OR reconciled_at IS NOT NULL OR (JSON_UNQUOTE(JSON_EXTRACT(outcome,'$.status')) IN('succeeded','client_cancelled','upstream_timeout','upstream_error','invalid_response','gateway_shutdown') AND COALESCE(JSON_UNQUOTE(JSON_EXTRACT(outcome,'$.error_code')),'')<>'gateway_interrupted') OR capacity_held),
    CONSTRAINT gateway_request_resolution_shape CHECK((state='admitted' AND resolved_at IS NULL AND outcome IS NULL AND outcome_sha256 IS NULL AND reported_at IS NULL AND reconciled_at IS NULL) OR (state='reported' AND resolved_at IS NOT NULL AND outcome IS NOT NULL AND outcome_sha256 IS NOT NULL AND reported_at IS NOT NULL) OR (state='reconciled' AND resolved_at IS NOT NULL AND outcome IS NULL AND outcome_sha256 IS NULL AND reported_at IS NULL AND reconciled_at IS NOT NULL)),
    CONSTRAINT gateway_request_reconciliation_shape CHECK((reconciled_at IS NULL AND reconciled_by IS NULL AND reconciliation_reason IS NULL) OR (reconciled_at IS NOT NULL AND reconciled_by IS NOT NULL AND reconciliation_reason IS NOT NULL AND CHAR_LENGTH(reconciliation_reason)>0)),
    CONSTRAINT gateway_requests_id_canonical CHECK(id IS NULL OR REGEXP_LIKE(id,'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c')),
    CONSTRAINT gateway_requests_tenant_id_canonical CHECK(tenant_id IS NULL OR REGEXP_LIKE(tenant_id,'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c')),
    CONSTRAINT gateway_requests_workspace_id_canonical CHECK(workspace_id IS NULL OR REGEXP_LIKE(workspace_id,'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c')),
    CONSTRAINT gateway_requests_node_id_canonical CHECK(node_id IS NULL OR REGEXP_LIKE(node_id,'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c')),
    CONSTRAINT gateway_requests_gateway_id_canonical CHECK(gateway_id IS NULL OR REGEXP_LIKE(gateway_id,'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c')),
    CONSTRAINT gateway_requests_api_key_id_canonical CHECK(api_key_id IS NULL OR REGEXP_LIKE(api_key_id,'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c')),
    CONSTRAINT gateway_requests_actor_user_id_canonical CHECK(actor_user_id IS NULL OR REGEXP_LIKE(actor_user_id,'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c')),
    CONSTRAINT gateway_requests_alias_id_canonical CHECK(alias_id IS NULL OR REGEXP_LIKE(alias_id,'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c')),
    CONSTRAINT gateway_requests_deployment_id_canonical CHECK(deployment_id IS NULL OR REGEXP_LIKE(deployment_id,'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c')),
    CONSTRAINT gateway_requests_reconciled_by_canonical CHECK(reconciled_by IS NULL OR REGEXP_LIKE(reconciled_by,'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c')),
    CONSTRAINT gateway_requests_active_recovery_id_canonical CHECK(active_recovery_id IS NULL OR REGEXP_LIKE(active_recovery_id,'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;
